public class Main {
    static <T> T firstOrNull(java.util.List<T> xs) {
        if (xs.isEmpty()) return null;
        return xs.get(0);
    }
    public static void main(String[] args) {
        System.out.println(firstOrNull(java.util.List.of("a", "b")));
    }
}
